static const char*arg(int argc,char**argv,const char*n){for(int i=2;i+1<argc;i++)if(!strcmp(argv[i],n))return argv[i+1];return NULL;}
static char*slurp(const char*p){FILE*f=fopen(p,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);return b;}
static char*field(const char*body,const char*schema,const char*truth){sqlite3*d=NULL;sqlite3_stmt*s=NULL;char*out=NULL;if(sqlite3_open(":memory:",&d)!=SQLITE_OK)return NULL;if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,'$.identity') WHERE json_valid(?1) AND json_extract(?1,'$.schema')=?2 AND json_extract(?1,'$.truth')=?3",-1,&s,NULL)==SQLITE_OK){sqlite3_bind_text(s,1,body,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,schema,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,truth,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW&&sqlite3_column_text(s,0))out=strdup((const char*)sqlite3_column_text(s,0));}sqlite3_finalize(s);sqlite3_close(d);return out;}
static int current_leases(sqlite3*d,const char*id){sqlite3_stmt*s=NULL;int n=-1;if(sqlite3_prepare_v2(d,"SELECT count(*) FROM material_lease WHERE identity=?1",-1,&s,NULL)==SQLITE_OK){sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW)n=sqlite3_column_int(s,0);}sqlite3_finalize(s);return n;}
static int retire_file(const char*dir,const char*schema,const char*truth,const char*identity){DIR*d=NULL;struct dirent*e;int retired=0;if(!dir||!(d=opendir(dir)))return 0;while((e=readdir(d))){char p[4096],to[4120],*body=NULL,*id=NULL;size_t z=strlen(e->d_name);if(e->d_name[0]=='.'||z<6||strcmp(e->d_name+z-5,".json")||snprintf(p,sizeof(p),"%s/%s",dir,e->d_name)>=(int)sizeof(p))continue;if(!(body=slurp(p)))continue;id=field(body,schema,truth);free(body);if(id&&!strcmp(id,identity)&&snprintf(to,sizeof(to),"%s.cancelled",p)<(int)sizeof(to)&&!rename(p,to)){retired++;free(id);break;}free(id);}closedir(d);return retired;}
static int clean_websub(sqlite3*d,const char*identity,int*pending,int*running,int*absent){sqlite3_stmt*q=NULL,*del=NULL,*count=NULL,*dirty=NULL,*drop=NULL;int ok=0;if(sqlite3_exec(d,"BEGIN IMMEDIATE",NULL,NULL,NULL)!=SQLITE_OK)return 0;if(sqlite3_prepare_v2(d,"SELECT topic FROM source_dirty_demand WHERE identity=?1 ORDER BY topic",-1,&q,NULL)!=SQLITE_OK)goto done;sqlite3_bind_text(q,1,identity,-1,SQLITE_TRANSIENT);while(sqlite3_step(q)==SQLITE_ROW){char*topic=strdup((const char*)sqlite3_column_text(q,0)),state[32]={0};int left=0;if(!topic)goto done;if(sqlite3_prepare_v2(d,"SELECT state FROM source_dirty WHERE topic=?1 LIMIT 1",-1,&dirty,NULL)!=SQLITE_OK){free(topic);goto done;}sqlite3_bind_text(dirty,1,topic,-1,SQLITE_TRANSIENT);if(sqlite3_step(dirty)==SQLITE_ROW&&sqlite3_column_text(dirty,0))snprintf(state,sizeof(state),"%s",sqlite3_column_text(dirty,0));sqlite3_finalize(dirty);dirty=NULL;if(sqlite3_prepare_v2(d,"DELETE FROM source_dirty_demand WHERE topic=?1 AND identity=?2",-1,&del,NULL)!=SQLITE_OK){free(topic);goto done;}sqlite3_bind_text(del,1,topic,-1,SQLITE_TRANSIENT);sqlite3_bind_text(del,2,identity,-1,SQLITE_TRANSIENT);if(sqlite3_step(del)!=SQLITE_DONE){free(topic);goto done;}sqlite3_finalize(del);del=NULL;if(sqlite3_prepare_v2(d,"SELECT count(*) FROM source_dirty_demand WHERE topic=?1",-1,&count,NULL)!=SQLITE_OK){free(topic);goto done;}sqlite3_bind_text(count,1,topic,-1,SQLITE_TRANSIENT);if(sqlite3_step(count)==SQLITE_ROW)left=sqlite3_column_int(count,0);sqlite3_finalize(count);count=NULL;if(!left&&!strcmp(state,"pending")){if(sqlite3_prepare_v2(d,"DELETE FROM source_dirty WHERE topic=?1 AND state='pending'",-1,&drop,NULL)!=SQLITE_OK){free(topic);goto done;}sqlite3_bind_text(drop,1,topic,-1,SQLITE_TRANSIENT);if(sqlite3_step(drop)!=SQLITE_DONE){free(topic);goto done;}sqlite3_finalize(drop);drop=NULL;(*pending)++;}else if(!strcmp(state,"running"))(*running)++;else if(!state[0])(*absent)++;free(topic);}ok=sqlite3_exec(d,"COMMIT",NULL,NULL,NULL)==SQLITE_OK;
done:sqlite3_finalize(q);sqlite3_finalize(del);sqlite3_finalize(count);sqlite3_finalize(dirty);sqlite3_finalize(drop);if(!ok)sqlite3_exec(d,"ROLLBACK",NULL,NULL,NULL);return ok;}
int main(int argc,char**argv){const char*croot=arg(argc,argv,"--cancel-dir"),*hroot=arg(argc,argv,"--handoff-dir"),*demands=arg(argc,argv,"--demand-dir"),*wdb=arg(argc,argv,"--websub-db"),*ldb=arg(argc,argv,"--lease-db");char cancellations[4096],handoffs[4096];DIR*d=NULL;struct dirent*e;sqlite3*web=NULL,*lease=NULL;int seen=0,suppressed=0,retired_h=0,retired_d=0,pending=0,running=0,absent=0,superseded=0,rejected=0;enum{WS_APPLY};static const BfCommandEntry gate_commands[]={{"apply",WS_APPLY,0,NULL},};const BfCommandEntry*command=argc<2?NULL:bf_command_lookup(gate_commands,sizeof(gate_commands)/sizeof(gate_commands[0]),argv[1]);if(argc<2||!command||command->id!=WS_APPLY||!croot||!hroot||!demands||!wdb||!ldb)return 2;if(snprintf(cancellations,sizeof(cancellations),"%s/MaterialCompiler-external",croot)>=(int)sizeof(cancellations)||snprintf(handoffs,sizeof(handoffs),"%s/MaterialCompiler-external",hroot)>=(int)sizeof(handoffs)||!(d=opendir(cancellations))||sqlite3_open(wdb,&web)!=SQLITE_OK||sqlite3_open_v2(ldb,&lease,SQLITE_OPEN_READONLY,NULL)!=SQLITE_OK)return 1;
 while((e=readdir(d))){char p[4096],handled[4120],*body=NULL,*identity=NULL;size_t z=strlen(e->d_name);if(e->d_name[0]=='.'||z<6||strcmp(e->d_name+z-5,".json")||snprintf(p,sizeof(p),"%s/%s",cancellations,e->d_name)>=(int)sizeof(p))continue;seen++;body=slurp(p);identity=body?field(body,"bonfyre-material-observation-cancel.v1","lease_count_zero_not_observation_retraction"):NULL;free(body);if(!identity){rejected++;continue;}int leases=current_leases(lease,identity);if(leases<0){free(identity);rejected++;continue;}if(leases>0)superseded++;else{retired_h+=retire_file(handoffs,"bonfyre-lowering-handoff.v1","dependency_cut_only",identity);retired_d+=retire_file(demands,"bonfyre-foreign-observation-demand.v1","observation_requested_not_performed",identity);if(!clean_websub(web,identity,&pending,&running,&absent)){free(identity);rejected++;continue;}suppressed++;}if(snprintf(handled,sizeof(handled),"%s.handled",p)>=(int)sizeof(handled)||rename(p,handled)){free(identity);rejected++;continue;}free(identity);}
 closedir(d);sqlite3_close(web);sqlite3_close(lease);printf("{\"cancellations_seen\":%d,\"suppressed\":%d,\"superseded\":%d,\"handoffs_retired\":%d,\"demands_retired\":%d,\"pending_topics_removed\":%d,\"running_too_late\":%d,\"completed_or_absent\":%d,\"rejected\":%d,\"truth\":\"zero_lease_pending_work_suppression_only\"}\n",seen,suppressed,superseded,retired_h,retired_d,pending,running,absent,rejected);return rejected?1:0;}
